#!/usr/bin/env python3
"""Five independently usable, privacy-first Worklane Tools MVPs for 2026-10-22."""
from pathlib import Path
import json, html
R=Path(__file__).resolve().parents[1]
STYLE='''
:root{--ink:#183644;--muted:#56727d;--teal:#08786f;--line:#d9e8e5;--bg:#f4faf8;--warn:#fff6e6}*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}main.app{max-width:1140px;margin:auto;padding:32px 18px 60px}
.eyebrow{color:var(--teal);font-weight:850;text-transform:uppercase;letter-spacing:1.2px;font-size:12px}h1{font-size:clamp(29px,4vw,45px);letter-spacing:-1.1px;line-height:1.13;margin:9px 0}h2{font-size:21px;margin:0 0 15px}h3{font-size:17px;margin:18px 0 6px}
.lead{font-size:17px;color:var(--muted);max-width:800px}.grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(310px,.9fr);gap:20px;margin-top:22px;align-items:start}.panel{background:white;border:1px solid var(--line);border-radius:17px;padding:22px;box-shadow:0 8px 30px #0b554009;min-width:0}
.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.fields.three{grid-template-columns:repeat(3,minmax(0,1fr))}label{display:flex;flex-direction:column;gap:5px;color:#3c606a;font-size:13px;font-weight:750}input,select,textarea{width:100%;min-width:0;border:1px solid #b6cfcc;border-radius:9px;padding:10px 11px;font:inherit;color:#173847;background:white}textarea{min-height:85px}input:focus,select:focus,textarea:focus{outline:3px solid #c5eee5;border-color:var(--teal)}button{border:1px solid #b6d7cf;background:#eaf7f3;color:#0a6d64;border-radius:10px;font:inherit;font-weight:800;font-size:14px;padding:10px 14px;cursor:pointer}button.primary{background:var(--teal);border-color:var(--teal);color:white}.actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:16px}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.metric{background:#ecf7f4;padding:13px;border-radius:11px;min-width:0}.metric small{display:block;color:#58737d}.metric strong{font-size:clamp(19px,2.6vw,27px);display:block;overflow-wrap:anywhere}.note{color:var(--muted);font-size:13px}.warning{background:var(--warn);border-left:3px solid #d9a54a;padding:12px 14px;margin-top:16px;font-size:13px}.row{border:1px solid var(--line);border-radius:11px;padding:12px;margin-top:10px}.row strong{display:block}.row small{display:block;color:#617b82}.row button{float:right;padding:4px 8px}.status{min-height:22px;color:#0c7669;font-size:13px}.prose{margin-top:22px;padding:22px;background:white;border:1px solid var(--line);border-radius:16px}.prose p,.prose li{color:#526c77}.wide{grid-column:1/-1}.chart{width:100%;height:180px;background:#f7fbfa;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;border-bottom:1px solid var(--line);padding:8px;word-break:break-word}th{color:#45616d}
@media(max-width:800px){.grid{grid-template-columns:1fr}.panel{padding:18px}}@media(max-width:470px){.fields,.fields.three{grid-template-columns:1fr}.app{padding:22px 12px}.metric strong{font-size:20px}}
@media print{body{background:white}.actions,.eyebrow,.warning,.prose{display:none!important}.panel{box-shadow:none}.grid{display:block}}
'''
COMMON_JS=r'''
const $=id=>document.getElementById(id);
const n=id=>Number($(id).value);
const usd=v=>Number(v).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function getLocal(key,def){try{const x=JSON.parse(localStorage.getItem(key));return x??def}catch{return def}}
function saveLocal(key,val){try{localStorage.setItem(key,JSON.stringify(val));return true}catch{if($('status'))$('status').textContent='Local storage unavailable. Export a backup now.';return false}}
function csv(rows){return '\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function download(data,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}
function finiteNonnegative(...vals){return vals.every(x=>Number.isFinite(x)&&x>=0)}
'''
def page(name,title,desc,body,script,article,category):
    schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':name,'description':desc,'applicationCategory':'BusinessApplication','operatingSystem':'Web','offers':{'@type':'Offer','price':'0','priceCurrency':'USD'}}
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | {name}</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta property="og:title" content="{html.escape(title,quote=True)} | {name}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:locale" content="en_US"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=True)}</script><style>{STYLE}</style></head><body><main class="app"><div class="eyebrow">Free browser tool · Local-first · No account</div><h1>{html.escape(title)}</h1><p class="lead">{html.escape(desc)}</p>{body}<section class="prose">{article}</section></main><script>{COMMON_JS}\n{script}</script></body></html>'''

apps={}
# 1. CONCRETE: custom yields, rectangular slab or round post-hole, multi-area, overage and cost.
body='''<div class="grid"><section class="panel"><h2>Add a concrete pour</h2><div class="fields"><label>Project section<input id="label" maxlength="80" value="Back patio"></label><label>Shape<select id="shape"><option value="slab">Rectangular slab</option><option value="hole">Round post holes</option></select></label><label>Length (feet)<input id="length" type="number" min="0.01" step="0.1" value="10"></label><label>Width (feet) / diameter (inches)<input id="width" type="number" min="0.01" step="0.1" value="8"></label><label>Depth / thickness (inches)<input id="depth" type="number" min="0.01" step="0.1" value="4"></label><label>Number of identical pours<input id="quantity" type="number" min="1" max="1000" step="1" value="1"></label></div><p class="note">For round holes, “length” is ignored and “width” is the diameter in inches.</p><div class="actions"><button class="primary" id="add">Add section</button><button id="export">Download takeoff CSV</button><button id="clear">Clear</button></div><p id="status" class="status" role="status"></p><div id="sections"></div></section><section class="panel"><h2>Concrete order estimate</h2><div class="fields"><label>Bag yield<select id="yield"><option value="0.6">80 lb bag · ~0.60 ft³</option><option value="0.45">60 lb bag · ~0.45 ft³</option><option value="0.3">40 lb bag · ~0.30 ft³</option><option value="custom">Custom yield</option></select></label><label>Custom bag yield (ft³)<input id="custom" type="number" min="0.01" step="0.01" value="0.6"></label><label>Overage allowance (%)<input id="waste" type="number" min="0" max="50" step="1" value="10"></label><label>Bag price ($)<input id="price" type="number" min="0" step="0.01" value="7.5"></label></div><div class="metrics" style="margin-top:18px"><div class="metric"><small>Base volume</small><strong id="ft3">0 ft³</strong></div><div class="metric"><small>With overage</small><strong id="yd3">0 yd³</strong></div><div class="metric"><small>Whole bags</small><strong id="bags">0</strong></div><div class="metric"><small>Bag material estimate</small><strong id="cost">$0</strong></div></div><p class="warning">Approximate volume only. Product yields vary. Verify bag labels, local requirements, base compaction, reinforcement and delivery options; this is not structural engineering or mix guidance.</p></section></div>'''
script=r'''
const KEY='concreteyield-v1';let sections=getLocal(KEY,[]);
function volume(x){if(x.shape==='slab')return x.l*x.w*x.d/12*x.q;return Math.PI*Math.pow(x.w/24,2)*(x.d/12)*x.q}
function render(){let base=sections.reduce((a,x)=>a+volume(x),0),extra=Math.min(50,Math.max(0,n('waste'))),yieldPer=$('yield').value==='custom'?n('custom'):Number($('yield').value),count=yieldPer>0?Math.ceil(base*(1+extra/100)/yieldPer):0;
$('ft3').textContent=base.toFixed(2)+' ft³';$('yd3').textContent=(base*(1+extra/100)/27).toFixed(3)+' yd³';$('bags').textContent=count.toLocaleString();$('cost').textContent=usd(count*Math.max(0,n('price')));
$('sections').innerHTML=sections.length?sections.map((x,i)=>`<div class="row"><button data-remove="${i}" aria-label="Remove section">Remove</button><strong>${esc(x.label)}</strong><small>${x.shape==='slab'?x.l+' × '+x.w+' ft':'Diameter '+x.w+' in'} · ${x.d} in depth · ×${x.q} · ${volume(x).toFixed(2)} ft³</small></div>`).join(''):'<p class="note">Add a slab or post-hole section to start.</p>'}
$('add').onclick=()=>{let x={label:$('label').value.trim()||'Section',shape:$('shape').value,l:n('length'),w:n('width'),d:n('depth'),q:n('quantity')};if(![x.l,x.w,x.d,x.q].every(Number.isFinite)||x.w<=0||x.d<=0||x.q<1||!Number.isInteger(x.q)||(x.shape==='slab'&&x.l<=0)){ $('status').textContent='Enter positive dimensions and a whole-number quantity.';return}sections.push(x);saveLocal(KEY,sections);render();$('status').textContent='Section added to this browser.'};
$('sections').onclick=e=>{let b=e.target.closest('[data-remove]');if(!b)return;sections.splice(+b.dataset.remove,1);saveLocal(KEY,sections);render()};
$('clear').onclick=()=>{if(confirm('Delete all sections from this device?')){sections=[];saveLocal(KEY,sections);render()}};
$('export').onclick=()=>download(csv([['section','shape','length_ft','width_ft_or_diameter_in','depth_in','quantity','volume_ft3'],...sections.map(x=>[x.label,x.shape,x.l,x.w,x.d,x.q,volume(x).toFixed(3)])]),'concrete-pour-takeoff.csv');
['yield','custom','waste','price'].forEach(id=>$(id).addEventListener('input',render));render();
'''
article='''<h2>Calculate concrete bags and cubic yards for several pours</h2><p>Contractors and DIY builders may know slab dimensions but struggle to reconcile bag counts, total weight and ready-mix volume. ConcreteYield sums rectangular slabs and round post holes separately, applies an explicit overage, then converts cubic feet to cubic yards and estimated whole bags.</p><h3>How the math works</h3><p>Rectangular volume = length × width × thickness in feet. Round-hole volume = π × radius² × depth, multiplied by hole count. Divide the volume including your chosen allowance by the product-specific bag yield and round up. Example yields of 0.60 ft³ for an 80 lb bag and 0.45 ft³ for a 60 lb bag are approximate; the package is authoritative.</p><p>Free competing calculators already exist. The possible differentiation is multi-section takeoffs, transparent yields, and CSV export—not a claim of higher structural accuracy.</p>'''
apps['concreteyield']=page('ConcreteYield','Concrete Bag & Cubic Yard Calculator for Multiple Pours','Estimate slab and round post-hole concrete volumes, bag quantities, overage and material cost with a printable CSV takeoff.',body,script,article,'contractors')

# 2. PHOTOVAULT: 5-year projected backup needs; sampled local files.
body='''<div class="grid"><section class="panel"><h2>Plan a photo archive</h2><div class="fields"><label>Photos captured per year<input id="photos" type="number" min="0" step="100" value="25000"></label><label>Average image size (MB)<input id="mb" type="number" min="0.1" step="0.1" value="35"></label><label>Video added per year (GB)<input id="video" type="number" min="0" step="1" value="200"></label><label>Annual growth (%)<input id="growth" type="number" min="0" max="200" step="1" value="10"></label><label>Years to plan<select id="years"><option>1</option><option>3</option><option selected>5</option><option>10</option></select></label><label>Local copy count<input id="copies" type="number" min="1" max="6" step="1" value="2"></label><label>Drive capacity (TB)<input id="drive" type="number" min="0.1" step="0.1" value="4"></label><label>Drive price ($)<input id="drivecost" type="number" min="0" step="1" value="110"></label><label>Cloud storage ($/TB/month)<input id="cloud" type="number" min="0" step="0.01" value="6.95"></label><label>Local files sample (optional)<input id="sample" type="file" multiple accept="image/*,video/*"></label></div><p class="note" id="sampleNote">Sample selection reads only file sizes in your browser; no upload. Select a few representative files, then choose “Use sample average”.</p><div class="actions"><button id="useSample">Use sample average</button><button class="primary" id="calculate">Recalculate</button><button id="export">Download annual plan CSV</button></div><p id="status" class="status" role="status"></p></section><section class="panel"><h2>Archive capacity forecast</h2><div class="metrics"><div class="metric"><small>Final-year unique data</small><strong id="unique">0 TB</strong></div><div class="metric"><small>Local drives needed</small><strong id="drives">0</strong></div><div class="metric"><small>Local hardware estimate</small><strong id="hardware">$0</strong></div><div class="metric"><small>Final-year cloud/month</small><strong id="cloudcost">$0</strong></div></div><h3>Year-by-year unique storage</h3><div style="overflow-x:auto"><table><thead><tr><th>Year</th><th>New TB</th><th>Total TB</th><th>Cloud/mo</th></tr></thead><tbody id="yearrows"></tbody></table></div><p class="warning">Capacity is not backup. Keep independent copies, including one offsite, and test restores. Prices are your inputs, not live vendor quotes. TB uses decimal units (1 TB = 1,000 GB).</p></section></div>'''
script=r'''
let plan=[];
function calc(){let count=n('photos'),mb=n('mb'),video=n('video'),growth=n('growth'),years=n('years'),copies=n('copies'),drive=n('drive'),drivecost=n('drivecost'),cloud=n('cloud');if(!finiteNonnegative(count,mb,video,growth,drivecost,cloud)||mb<=0||growth>200||copies<1||copies>6||!Number.isInteger(copies)||drive<=0){$('status').textContent='Check sizes, growth, copies and drive capacity.';return}let total=0;plan=[];for(let i=1;i<=years;i++){let annual=((count*mb/1000)+video)/1000*Math.pow(1+growth/100,i-1);total+=annual;plan.push({year:i,newtb:annual,total,monthly:total*cloud})}
$('unique').textContent=total.toFixed(2)+' TB';$('drives').textContent=Math.ceil(total/drive)*copies;$('hardware').textContent=usd(Math.ceil(total/drive)*copies*drivecost);$('cloudcost').textContent=usd(total*cloud);$('yearrows').innerHTML=plan.map(x=>`<tr><td>${x.year}</td><td>${x.newtb.toFixed(2)}</td><td>${x.total.toFixed(2)}</td><td>${usd(x.monthly)}</td></tr>`).join('');$('status').textContent='Estimate updated. Review vendor backup scope and offsite requirements.'}
$('calculate').onclick=calc;['photos','mb','video','growth','years','copies','drive','drivecost','cloud'].forEach(id=>$(id).oninput=calc);
$('useSample').onclick=()=>{let files=[...$('sample').files].filter(f=>f.size>0);if(!files.length){$('status').textContent='Choose sample files first.';return}let images=files.filter(f=>f.type.startsWith('image/'));if(!images.length){$('status').textContent='Select image files to calculate an image-size average.';return}let average=images.reduce((s,f)=>s+f.size,0)/images.length/1e6;$('mb').value=average.toFixed(2);$('sampleNote').textContent=`${images.length} local image files sampled; average ${average.toFixed(2)} MB. Files were not uploaded.`;calc()};
$('export').onclick=()=>{if(!plan.length){$('status').textContent='Calculate first.';return}download(csv([['year','new_tb_decimal','cumulative_tb_decimal','cloud_monthly_usd'],...plan.map(x=>[x.year,x.newtb.toFixed(3),x.total.toFixed(3),x.monthly.toFixed(2)])]),'photo-storage-capacity-plan.csv')};calc();
'''
article='''<h2>Estimate photo backup storage before buying another drive</h2><p>A photography archive grows differently from a phone photo library: RAW files, edited exports, video and redundant copies add up. PhotoVaultPlan forecasts yearly unique storage and then separately estimates how many physical drives are needed for a user-chosen number of local copies.</p><h3>What this forecast does not do</h3><p>The cloud estimate is a storage-only hypothetical based on the rate you enter. It excludes transfer charges, minimum billing, retention policies, drive replacement, NAS enclosures and restore costs. Unlimited-computer backup products and object storage have different rules; compare the vendor plan before purchasing. Choosing a file sample never uploads the files.</p><p>Use a 3-2-1-style backup plan as a starting point, and verify recoverability with restore tests. RAID redundancy alone does not protect against accidental deletion or site loss.</p>'''
apps['photovaultplan']=page('PhotoVaultPlan','Photographer Backup Storage & Drive Cost Planner','Forecast RAW photo and video storage, redundant local drives, and estimated cloud costs across 1–10 years without uploading files.',body,script,article,'photographers')

# 3. RESERVE: property reserve planning.
body='''<div class="grid"><section class="panel"><h2>Add a rental property</h2><div class="fields"><label>Property label<input id="name" maxlength="80" value="Duplex A"></label><label>Monthly rent ($)<input id="rent" type="number" min="0" step="1" value="2400"></label><label>Annual routine repairs ($)<input id="repairs" type="number" min="0" step="1" value="2400"></label><label>Target emergency reserve ($)<input id="target" type="number" min="0" step="100" value="6000"></label><label>Current reserve ($)<input id="current" type="number" min="0" step="100" value="1200"></label><label>Monthly contribution (%) of rent<input id="percent" type="number" min="0" max="100" step="0.5" value="10"></label></div><div class="actions"><button class="primary" id="add">Add property</button><button id="export">Export reserve plan CSV</button><button id="clear">Clear properties</button></div><p id="status" class="status" role="status"></p><div id="properties"></div></section><section class="panel"><h2>Maintenance reserve outlook</h2><div class="metrics"><div class="metric"><small>Monthly contributions</small><strong id="contrib">$0</strong></div><div class="metric"><small>Routine repairs / month</small><strong id="routine">$0</strong></div><div class="metric"><small>Projected reserve at month 12</small><strong id="balance">$0</strong></div><div class="metric"><small>Target shortfall at month 12</small><strong id="gap">$0</strong></div></div><h3>Unexpected repair scenario</h3><div class="fields"><label>One-time repair ($)<input id="shock" type="number" min="0" step="100" value="3500"></label><label>Repair occurs in month<select id="month"><option>1</option><option>3</option><option selected>6</option><option>9</option><option>12</option></select></label></div><div class="metric" style="margin-top:10px"><small>Minimum projected balance with repair</small><strong id="minimum">$0</strong></div><p class="warning">Budgeting illustration only. This does not predict actual failures, account for taxes or vacancy, or replace an inspection, insurance or professional financial advice. Negative balances mean a funding gap.</p></section></div>'''
script=r'''
const KEY='reserveready-v1';let properties=getLocal(KEY,[]);let last=[];
function render(){let contribution=properties.reduce((s,x)=>s+x.rent*x.percent/100,0),routine=properties.reduce((s,x)=>s+x.repairs/12,0),initial=properties.reduce((s,x)=>s+x.current,0),target=properties.reduce((s,x)=>s+x.target,0),shock=Math.max(0,n('shock')),month=n('month');let balance=initial,min=initial;last=[];for(let i=1;i<=12;i++){balance+=contribution-routine-(i===month?shock:0);min=Math.min(min,balance);last.push({month:i,balance})}let normal=initial+12*(contribution-routine);
$('contrib').textContent=usd(contribution);$('routine').textContent=usd(routine);$('balance').textContent=usd(normal);$('gap').textContent=usd(Math.max(0,target-normal));$('minimum').textContent=usd(min);
$('properties').innerHTML=properties.length?properties.map((x,i)=>`<div class="row"><button data-remove="${i}">Remove</button><strong>${esc(x.name)}</strong><small>${usd(x.rent)} rent / month · ${usd(x.repairs)} annual repairs · ${x.percent}% contributed</small></div>`).join(''):'<p class="note">Add a property to build a reserve plan.</p>'}
$('add').onclick=()=>{let x={name:$('name').value.trim()||'Property',rent:n('rent'),repairs:n('repairs'),target:n('target'),current:n('current'),percent:n('percent')};if(!finiteNonnegative(x.rent,x.repairs,x.target,x.current,x.percent)||x.percent>100){$('status').textContent='Enter nonnegative values and a contribution from 0–100%.';return}properties.push(x);saveLocal(KEY,properties);render();$('status').textContent='Property saved locally.'};
$('properties').onclick=e=>{let b=e.target.closest('[data-remove]');if(!b)return;properties.splice(+b.dataset.remove,1);saveLocal(KEY,properties);render()};$('clear').onclick=()=>{if(confirm('Clear property budgets from this device?')){properties=[];saveLocal(KEY,properties);render()}};
['shock','month'].forEach(id=>$(id).oninput=render);
$('export').onclick=()=>download(csv([['property','monthly_rent','annual_repairs','reserve_target','current_reserve','contribution_pct'],...properties.map(x=>[x.name,x.rent,x.repairs,x.target,x.current,x.percent])]),'rental-maintenance-reserve-plan.csv');render();
'''
article='''<h2>Plan maintenance reserves across small rental portfolios</h2><p>Landlords often know monthly rent but do not separate routine maintenance from the cash reserve needed for larger repairs. ReserveReady adds multiple properties, projects a 12-month cash reserve after recurring contributions and routine expenses, and tests one unexpected repair event.</p><h3>Interpret the scenario, not just the total</h3><p>A positive year-end balance can hide a midyear cash shortage. The minimum balance includes the selected repair month, so you can see whether an earlier expense creates a funding gap. Contributions and target amounts are your assumptions, not standardized industry rules.</p><p>All property labels and amounts stay in browser local storage. Export a CSV if you need to preserve your budget or discuss it with an accountant.</p>'''
apps['reserveready']=page('ReserveReady','Rental Property Maintenance Reserve Planner','Estimate monthly maintenance contributions, emergency reserve shortfalls, and 12-month cash balances across multiple rental properties.',body,script,article,'landlords')

# 4. MARGINWATCH: quoted fixed price, logged hours, costs and forecast.
body='''<div class="grid"><section class="panel"><h2>Fixed-price project budget</h2><div class="fields"><label>Project label<input id="project" maxlength="80" value="Website redesign"></label><label>Client quote / revenue ($)<input id="quote" type="number" min="0" step="1" value="6000"></label><label>Planned work hours<input id="budget" type="number" min="0.1" step="0.5" value="60"></label><label>Internal labor cost per hour ($)<input id="hourly" type="number" min="0" step="1" value="45"></label><label>Fixed outside costs ($)<input id="expenses" type="number" min="0" step="1" value="400"></label><label>Estimated hours remaining<input id="remaining" type="number" min="0" step="0.5" value="15"></label></div><h3>Add completed work</h3><div class="fields"><label>Work note<input id="note" maxlength="90" placeholder="Client revisions"></label><label>Hours worked<input id="hours" type="number" min="0.1" step="0.25" value="4"></label></div><div class="actions"><button class="primary" id="add">Log hours</button><button id="export">Export work CSV</button><button id="reset">Reset project</button></div><p id="status" class="status" role="status"></p><div id="logs"></div></section><section class="panel"><h2>Profitability as work progresses</h2><div class="metrics"><div class="metric"><small>Hours logged</small><strong id="worked">0</strong></div><div class="metric"><small>Budget hours remaining</small><strong id="headroom">0</strong></div><div class="metric"><small>Current contribution</small><strong id="current">$0</strong></div><div class="metric"><small>Forecast profit at completion</small><strong id="forecast">$0</strong></div><div class="metric"><small>Forecast margin</small><strong id="margin">0%</strong></div><div class="metric"><small>Forecast vs planned profit</small><strong id="delta">$0</strong></div></div><p class="warning">Planning tool, not accounting software. Internal hourly cost is your own cost assumption, not the rate charged to the client. Taxes, payment risk and untracked overhead are excluded. No Toggl or invoice integration.</p></section></div>'''
script=r'''
const KEY='marginwatch-v1';let state=getLocal(KEY,{project:'Website redesign',quote:6000,budget:60,hourly:45,expenses:400,remaining:15,logs:[]});
function persist(){['project','quote','budget','hourly','expenses','remaining'].forEach(id=>state[id]=id==='project'?$(id).value:n(id));saveLocal(KEY,state)}
function render(){let worked=state.logs.reduce((s,x)=>s+x.hours,0),quote=n('quote'),budget=n('budget'),rate=n('hourly'),expenses=n('expenses'),remaining=n('remaining');if(!finiteNonnegative(quote,budget,rate,expenses,remaining)){$('status').textContent='Use nonnegative budget and cost values.';return}
let planned=quote-budget*rate-expenses,current=quote-worked*rate-expenses,forecast=quote-(worked+remaining)*rate-expenses;
$('worked').textContent=worked.toFixed(2)+' h';$('headroom').textContent=(budget-worked).toFixed(2)+' h';$('current').textContent=usd(current);$('forecast').textContent=usd(forecast);$('margin').textContent=quote>0?(forecast/quote*100).toFixed(1)+'%':'n/a';$('delta').textContent=usd(forecast-planned);
$('logs').innerHTML=state.logs.length?state.logs.map((x,i)=>`<div class="row"><button data-remove="${i}">Remove</button><strong>${esc(x.note)}</strong><small>${x.hours} hours · ${esc(x.date)}</small></div>`).join(''):'<p class="note">Log completed work to compare actual hours against the estimate.</p>'}
['project','quote','budget','hourly','expenses','remaining'].forEach(id=>{$(id).value=state[id]});
['project','quote','budget','hourly','expenses','remaining'].forEach(id=>$(id).oninput=()=>{persist();render()});
$('add').onclick=()=>{let hrs=n('hours');if(!Number.isFinite(hrs)||hrs<=0||hrs>5000){$('status').textContent='Enter positive hours for this work entry.';return}state.logs.push({note:$('note').value.trim()||'Work session',hours:hrs,date:new Date().toISOString().slice(0,10)});saveLocal(KEY,state);render();$('status').textContent='Hours saved locally.'};
$('logs').onclick=e=>{let b=e.target.closest('[data-remove]');if(!b)return;state.logs.splice(+b.dataset.remove,1);saveLocal(KEY,state);render()};
$('reset').onclick=()=>{if(confirm('Clear project and time entries?')){localStorage.removeItem(KEY);location.reload()}};
$('export').onclick=()=>download(csv([['project','note','hours','date','client_quote','hourly_cost','fixed_costs'],...state.logs.map(x=>[state.project,x.note,x.hours,x.date,state.quote,state.hourly,state.expenses])]),'freelance-project-profitability.csv');render();
'''
article='''<h2>Catch a fixed-price project margin problem before delivery</h2><p>Tracking time is not the same as knowing whether a project remains profitable. MarginWatch compares a fixed client quote with internal labor cost, outside expenses, actual logged hours and an explicit remaining-hours estimate. The completion forecast updates every time you log work.</p><h3>What “margin” means here</h3><p>Forecast profit = quote − (completed hours + estimated remaining hours) × internal labor cost − fixed outside costs. Forecast margin = forecast profit ÷ quote, when quote is greater than zero. This is a contribution estimate, not a tax return or full financial statement.</p><p>Use the gap between planned and forecast profit as a prompt to renegotiate scope or improve estimation—not as proof a client owes more money. Entries stay in local storage and can be exported to CSV.</p>'''
apps['marginwatch']=page('MarginWatch','Freelance Fixed-Price Project Profitability Tracker','Track actual project hours and costs against a fixed client quote to forecast profit, margin, and budget overruns before delivery.',body,script,article,'freelancers')

# 5. TRAVELBUFFER: appointments plus travel buffer conflicts; .ics export.
body='''<div class="grid"><section class="panel"><h2>Add an on-site appointment</h2><div class="fields"><label>Client / job label<input id="client" maxlength="80" value="Home consultation"></label><label>Appointment date<input id="date" type="date"></label><label>Start time (your device time zone)<input id="time" type="time" value="10:00"></label><label>Appointment duration (minutes)<input id="duration" type="number" min="5" max="1440" step="5" value="60"></label><label>Travel / prep before (minutes)<input id="before" type="number" min="0" max="1440" step="5" value="45"></label><label>Travel / wrap-up after (minutes)<input id="after" type="number" min="0" max="1440" step="5" value="30"></label></div><div class="actions"><button class="primary" id="add">Add appointment</button><button id="ics">Download blocked-time calendar (.ics)</button><button id="export">Export CSV</button><button id="clear">Clear</button></div><p id="status" class="status" role="status"></p><div id="appointments"></div></section><section class="panel"><h2>Travel-aware schedule</h2><div class="metrics"><div class="metric"><small>Appointments</small><strong id="count">0</strong></div><div class="metric"><small>Overlapping pairs</small><strong id="conflicts">0</strong></div><div class="metric"><small>Client-facing minutes</small><strong id="service">0</strong></div><div class="metric"><small>Reserved travel/buffer minutes</small><strong id="travel">0</strong></div></div><p class="warning">This does not estimate driving time, access traffic, sync with a live calendar, prevent external bookings or send invitations. You enter buffer durations. Calendar export uses the time zone of this device at creation; verify imported times, especially when traveling.</p></section></div>'''
script=r'''
const KEY='travelbuffer-v1';let jobs=getLocal(KEY,[]);function asDate(x){return new Date(x.date+'T'+x.time+':00')}function intervals(x){let s=asDate(x).getTime();return {start:s-x.before*60000,service:s,end:s+(x.duration+x.after)*60000}}function fmt(ms){return new Date(ms).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
function render(){jobs.sort((a,b)=>intervals(a).start-intervals(b).start);let conflicts=0;for(let i=0;i<jobs.length;i++)for(let j=i+1;j<jobs.length;j++){let a=intervals(jobs[i]),b=intervals(jobs[j]);if(a.start<b.end&&b.start<a.end)conflicts++}
$('count').textContent=jobs.length;$('conflicts').textContent=conflicts;$('service').textContent=jobs.reduce((s,x)=>s+x.duration,0);$('travel').textContent=jobs.reduce((s,x)=>s+x.before+x.after,0);
$('appointments').innerHTML=jobs.length?jobs.map((x,i)=>{let t=intervals(x);return `<div class="row"><button data-remove="${i}">Remove</button><strong>${esc(x.client)}</strong><small>Appointment: ${fmt(t.service)} · ${x.duration} min</small><small>Calendar blocked: ${fmt(t.start)} – ${fmt(t.end)}</small></div>`}).join(''):'<p class="note">Add appointments to check whether travel buffers collide.</p>';saveLocal(KEY,jobs)}
function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(new Date(s+'T12:00:00').getTime())}
$('add').onclick=()=>{let x={client:$('client').value.trim()||'Appointment',date:$('date').value,time:$('time').value,duration:n('duration'),before:n('before'),after:n('after')};if(!validDate(x.date)||!/^\d{2}:\d{2}$/.test(x.time)||!finiteNonnegative(x.duration,x.before,x.after)||x.duration<5||x.duration>1440||x.before>1440||x.after>1440){$('status').textContent='Enter a valid date, time, duration and buffer minutes.';return}jobs.push(x);render();$('status').textContent='Appointment added locally. Check conflicts before sharing.'};
$('appointments').onclick=e=>{let b=e.target.closest('[data-remove]');if(!b)return;jobs.splice(+b.dataset.remove,1);render()};$('clear').onclick=()=>{if(confirm('Clear appointments from this browser?')){jobs=[];render()}};
$('export').onclick=()=>download(csv([['client','date','start_time','duration_minutes','before_minutes','after_minutes'],...jobs.map(x=>[x.client,x.date,x.time,x.duration,x.before,x.after])]),'travel-buffer-schedule.csv');
function utcStamp(ms){return new Date(ms).toISOString().replaceAll('-','').replaceAll(':','').replace(/\.\d{3}Z$/,'Z')}
function icsEscape(s){return String(s).replaceAll('\\','\\\\').replaceAll(';','\\;').replaceAll(',','\\,').replaceAll('\n','\\n')}
$('ics').onclick=()=>{if(!jobs.length){$('status').textContent='Add an appointment before exporting.';return}let events=jobs.map((x,i)=>{let t=intervals(x);return ['BEGIN:VEVENT','UID:worklane-travelbuffer-'+i+'-'+t.start+'@local','DTSTAMP:'+utcStamp(Date.now()),'DTSTART:'+utcStamp(t.start),'DTEND:'+utcStamp(t.end),'SUMMARY:'+icsEscape('Reserved: '+x.client),'DESCRIPTION:'+icsEscape('Client appointment starts '+fmt(t.service)+'. Includes '+x.before+' minutes before and '+x.after+' minutes after. Verify time zone and travel. No invitation sent.'),'TRANSP:OPAQUE','END:VEVENT'].join('\r\n')});download('BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Worklane Tools//TravelBuffer//EN\r\nCALSCALE:GREGORIAN\r\n'+events.join('\r\n')+'\r\nEND:VCALENDAR\r\n','travel-buffer-appointments.ics','text/calendar;charset=utf-8');$('status').textContent='Calendar file saved. Import and verify the blocked times.'};
(function(){let d=new Date();d.setDate(d.getDate()+1);$('date').value=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')})();render();
'''
article='''<h2>Block travel time around appointments, not just the appointment itself</h2><p>On-site consultants, tutors, inspectors and other mobile service providers may need a 60-minute client appointment but 45 minutes to drive there and 30 minutes afterward. Standard calendar events that reserve only the client-facing time can create double bookings.</p><h3>How the conflict check works</h3><p>Each appointment has a blocked start (scheduled start minus pre-visit buffer) and blocked end (scheduled end plus post-visit buffer). Overlapping blocked intervals count as conflicts. Export an iCalendar file that reserves the entire block as busy, then import it into your calendar and verify its time zone.</p><p>This MVP does not calculate route times or expose a booking page to clients. It solves the planning and calendar-export task only; real-time booking integration is a future hypothesis.</p>'''
apps['travelbuffer']=page('TravelBuffer','Appointment Travel Buffer & Calendar Conflict Planner','Plan on-site appointments with pre/post travel buffers, detect schedule overlaps and export blocked-time iCalendar events.',body,script,article,'freelancers')

for slug,content in apps.items():
    f=R/'apps'/slug/'index.html';f.parent.mkdir(parents=True,exist_ok=True);f.write_text(content,encoding='utf-8')
print('Wrote',len(apps),'working HTML/JS applications')
